const OTT_GR_SUM = {"G1453": 9751.4, "G1456": 71456.73347381577, "G1459": 71445.093255458, "G1462": 71428.97603003956, "G1465": 71411.06800179684, "G1468": 71394.05537496625, "G1471": 71380.62435378421, "G1474": 71373.46114248713, "G1475": 36051.590000000004, "G1480": 36051.590000000004, "G1485": 36051.590000000004, "G1500": 39705.25, "G1501": 39705.25, "G1520": 19536.84, "G1523": 19536.84, "G1540": 43380.99, "G1541": 43380.99, "G1560": 56421.57, "G1567": 56421.57, "G1580": 63891.5, "G1600": 48242.29, "G1625": 74429.84, "G1646": 74429.84, "G1647": 74429.84, "G1650": 79875.81, "G1670": 79875.81, "G1683": 76614.69, "G1684": 76614.69, "G1685": 76614.69, "G1686": 76614.69, "G1687": 76614.69, "G1690": 76614.69, "G1699": 93772.36, "G1715": 93772.36, "G1716": 93772.36, "G1718": 93772.36, "G1740": 93772.36, "G1757": 122001.77, "G1760": 104188.43, "G1780": 42189.63, "G1787": 66189.97, "G1797": 66189.97, "G1798": 66189.97, "G1800": 18552.940000000002, "G1808": 18552.940000000002};

const INF = { start: -Infinity, end: Infinity };
const closed = (r) => (r[0][0] === r[r.length - 1][0] && r[0][1] === r[r.length - 1][1] ? r : [...r, r[0]]);
const resolveInline = (r) => (r && typeof r === 'object' && Array.isArray(r.ring) ? ensureClockwise(closed(r.ring)) : null);
const checksum = (ring) => ring.reduce((s, [x, y]) => s + x * 7 + y * 13, 0);
const rid = (r) => (typeof r === 'string' ? r : r.id);

/** Drop Venice's schematic Crete and Ionian regions and rebuild the Ottoman ring (run after the Albania fixes). */
export function applyGreeceShapeFixes(entities) {
  const venice = entities.find((e) => e.id === 'venice');
  if (!venice) throw new Error('greece fixes: no venice');
  venice.overlays = venice.overlays.map((o) => ({ ...o, regions: o.regions.filter((r) => !['crete-foothold', 'ionian-fringe'].includes(rid(r))) }));
  if (!OTT_GR_PLAN.length) return;
  const ott = entities.find((e) => e.id === 'ottoman-empire');
  if (!ott) throw new Error('greece fixes: no ottoman-empire');
  const src = { ...ott, overlays: ott.overlays.slice() };
  const lo = OTT_GR_PLAN[0][0];
  const hi = OTT_GR_PLAN[OTT_GR_PLAN.length - 1][0];
  if (!src.overlays.some((o) => o.year === lo) || !src.overlays.some((o) => o.year === hi + 1)) throw new Error('greece fixes: ottoman-empire keyframes changed');
  const seen = new Set();
  const made = OTT_GR_PLAN.map(([y, key]) => {
    const parts = morphEntityAtYear(src, y, resolveInline, INF, 20, resolveRegionHoles);
    const part = parts.find((p) => p.regionId === 'anatolia-balkans');
    if (!part) throw new Error(`greece fixes: no anatolia-balkans at ${y}`);
    if (!seen.has(key)) {
      seen.add(key);
      if (Math.abs(checksum(part.ring) - OTT_GR_SUM[key]) > 1e-6) throw new Error(`greece fixes: ottoman anatolia-balkans at ${y} changed — regenerate the ${key} trim`);
    }
    let base = src.overlays[0];
    for (const o of src.overlays) if (o.year <= y) base = o;
    const cut = OTT_GR_RINGS[key];
    const regions = parts.map((p) => {
      if (p.regionId === 'anatolia-balkans' && cut) return { id: p.regionId, name: p.regionName, ring: cut.ring, ...(cut.holes.length ? { holes: cut.holes } : {}) };
      return { id: p.regionId, name: p.regionName, ring: p.ring, ...(p.holes.length ? { holes: p.holes } : {}) };
    });
    return { year: y, label: base.label, approximation: base.approximation, regions };
  });
  ott.overlays = [...src.overlays.filter((o) => o.year < lo || o.year > hi), ...made].sort((a, b) => a.year - b.year);
}
